 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))
    return comps


def _shape(cells):
    min_r = min(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    return frozenset((r-min_r, c-min_c) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    reference_shapes = {_shape(cells) for color, cells in comps if color == 8}
    for color, cells in comps:
        if color != 8 and _shape(cells) in reference_shapes:
            for r, c in cells:
                out[r][c] = 8
    return out
